  // EAR = (||p2-p6|| + ||p3-p5||) / (2 * ||p1-p4||)
  // Vertical distances / horizontal distance

  const p1 = eyeLandmarks[0];
  const p2 = eyeLandmarks[1];
  const p3 = eyeLandmarks[2];
  const p4 = eyeLandmarks[3];
  const p5 = eyeLandmarks[4];
  const p6 = eyeLandmarks[5];
