  // If no strong liveness signal AND score is only from noise/partial credits
  const hasNoBlinkOrMovement = blinkCount === 0 && microMovement < 1.5 && poseVariance < 3;

  if (hasNoBlinkOrMovement && duration >= 3000) {
    // Static face for 3+ seconds with no genuine movement - likely photo
    // Force score down to prevent false LIVE
    score = Math.min(score, 25); // Cap at 25% max for static faces
    factors.push({
      name: '⚠️ Static Face Gate',
      score: 0,
      status: 'fail',
      reason: 'No blink or meaningful movement detected'
    });
  }

  // Normalize to 0-1
  const confidence = Math.min(1, score / 100);

  // Enhanced diagnostic logging
  console.log('📊 Liveness Score Result:', {
    confidence: (confidence * 100).toFixed(1) + '%',
    rawScore: score.toFixed(1),
    hasStrongSignal: hasStrongLivenessSignal,
    staticFaceGateTriggered: hasNoBlinkOrMovement && duration >= 3000,
    factors: factors.map(f => `${f.name}: ${f.score}`)
  });

  // Detailed decision reasoning
  const livenessEvidence = {
    validBlink: blinkCount >= 1,
    meaningfulMovement: microMovement > 1.5,
    depthDetected: depthScore > 2,
    eyeMovement: earVariance > 0.0005,
    headMovement: poseVariance > 3
  };

  console.log('🎯 Liveness Evidence:', livenessEvidence);

  // Decision logic explanation
  let decision = 'UNCERTAIN';
  if (confidence >= 0.65 && hasStrongLivenessSignal) {
    decision = 'LIVE';
  } else if (confidence < 0.30 || (hasNoBlinkOrMovement && duration >= 3000)) {
    decision = 'SPOOF';
  }

  console.log('✅ Decision:', decision, '- Confidence:', (confidence * 100).toFixed(1) + '%');

  return {
    confidence,
    rawScore: score,
    factors,
    blinkCount,
    timeSinceLastBlink,
    microMovement,
    depthScore,
    hasStrongLivenessSignal,
    livenessEvidence
  };
};

// Process frame for liveness detection
export const processLivenessFrame = (landmarks, imageWidth, imageHeight) => {
  // Extract eye landmarks
  const eyes = getEyeLandmarks(landmarks);

  // Calculate Eye Aspect Ratio for both eyes
  const leftEAR = calculateEyeAspectRatio(eyes.left);
  const rightEAR = calculateEyeAspectRatio(eyes.right);
  const avgEAR = (leftEAR + rightEAR) / 2;

  // Calculate head pose
  const pose = calculateHeadPose(landmarks, imageWidth, imageHeight);

  // Analyze 3D depth
  const depth = analyze3DDepth(landmarks);

  return {
    ear: avgEAR,
    pose,
    depth,
    timestamp: Date.now()
  };
};

export default {
  processLivenessFrame,
  detectBlinks,
  detectMicroMovements,
  analyze3DDepth,
  calculateLivenessScore
};
